#include <oauth/GoogleDriveBackupClient.hpp>
#include <QCoreApplication>
#include "facts.hpp"
#include <iostream>
#include <thread>
using namespace std;
int checks=0, failures=0;
void Check(bool ok,const char*n){++checks;if(!ok){++failures;cerr<<"FAIL "<<n<<'\n';}}
using Session=GoogleDriveBackupClient::SessionInfo;
OAuthTokenSet Tokens(){OAuthTokenSet t;t.accessToken="qa-store-new";t.refreshToken="qa-store-refresh";t.expiresAt=4102444800;return t;}
Session Observe(){QString error;Session s;GoogleDriveBackupClient::HasConnection(error,{},&s);Check(error.isEmpty()&&s.epoch>0,"worker credential snapshot established");return s;}
void RejectStore(bool oldPresent){ResetFacts();if(oldPresent)SeedCloud();auto old=CloudRaw();auto session=Observe();QString error;auto lease=GoogleDriveBackupClient::BeginCredentialTransaction(session,error,{});Check(bool(lease),"Store lease acquired");auto tokens=Tokens();Check(lease&&lease->Store(tokens,error),"tentative Store actually writes before GUI rejection");auto staged=CloudRaw();Check(staged&&staged!=old,"tentative Store RAW differs from original");Check(lease&&lease->Rollback(error)&&CloudRaw()==old,"rejected Store restores exact RAW or original absence");lease.reset();Check(GoogleDriveBackupClient::SessionCurrent(session),"successful rollback preserves prior opaque session");}
void AmbiguousStore(bool failRecovery){ResetFacts();SeedCloud();auto old=CloudRaw();auto session=Observe();QString error;auto request=make_shared<SecureTokenStore::RequestContext>();auto lease=GoogleDriveBackupClient::BeginCredentialTransaction(session,error,request);saveCommitCancel=true;Check(lease&&!lease->Store(Tokens(),error)&&request->IsCancelled(),"ambiguous Save commits before cancellation/failure reply");auto staged=CloudRaw();Check(staged&&staged!=old,"ambiguous Save left tentative RAW before recovery");if(failRecovery)failSave=true;bool restored=lease&&lease->Rollback(error);Check(failRecovery?(!restored&&CloudRaw()==staged&&error.contains(QStringLiteral("não foi confirmada"))):(restored&&CloudRaw()==old),"fresh recovery outcome explicit and never silently reports success");lease.reset();Check(failRecovery?!GoogleDriveBackupClient::SessionCurrent(session):GoogleDriveBackupClient::SessionCurrent(session),"session invalidates only when recovery cannot be confirmed");}
void ExternalAfterStore(bool absent){ResetFacts();SeedCloud();auto session=Observe();QString error;auto lease=GoogleDriveBackupClient::BeginCredentialTransaction(session,error,{});Check(lease&&lease->Store(Tokens(),error),"external-conflict fixture Store reached");optional<string> external=absent?nullopt:optional<string>(R"({"access_token":"qa-external-owner","extra":"external"})");ReplaceCloudRaw(external);int before=saves;Check(lease&&!lease->Rollback(error)&&error.contains(QStringLiteral("não foi confirmada")),"unexpected present/absent external state reports incomplete reconciliation");Check(CloudRaw()==external&&saves==before,"Store recovery never recreates old account over external replacement/removal");lease.reset();Check(!GoogleDriveBackupClient::SessionCurrent(session),"incomplete Store recovery invalidates old session identity");}
void StoreCommit(){ResetFacts();SeedCloud();auto old=Observe();QString error;auto lease=GoogleDriveBackupClient::BeginCredentialTransaction(old,error,{});Check(lease&&lease->Store(Tokens(),error),"Store Commit fixture mutation reached");auto committed=lease->Commit();lease.reset();auto read=Observe();Check(committed.connected&&committed.epoch==read.epoch&&!GoogleDriveBackupClient::SessionCurrent(old),"Store Commit advances epoch once and publishes connected identity");Check(GoogleDriveBackupClient::SessionCurrent(committed),"committed Store identity remains current on subsequent RAW Load");}
void FailedSaveNoMutation(){ResetFacts();SeedCloud();auto raw=CloudRaw();auto session=Observe();QString error;auto lease=GoogleDriveBackupClient::BeginCredentialTransaction(session,error,{});failSave=true;Check(lease&&!lease->Store(Tokens(),error),"provider rejects tentative Store before mutation");Check(lease&&lease->Rollback(error)&&CloudRaw()==raw,"failed Save does not rewrite intact old RAW even if recovery Save unavailable");lease.reset();}
void CancelBeforeBegin(){ResetFacts();SeedCloud();auto old=Observe();const int before=loads;auto request=make_shared<SecureTokenStore::RequestContext>();request->Cancel();QString error;auto lease=GoogleDriveBackupClient::BeginCredentialTransaction(old,error,request);Check(!lease&&loads==before&&saves==0&&!error.isEmpty(),"cancel before Begin performs no additional keyring IO");}
void OneMutationOnly(){ResetFacts();SeedCloud();auto old=CloudRaw();auto session=Observe();QString error;auto lease=GoogleDriveBackupClient::BeginCredentialTransaction(session,error,{});Check(lease&&lease->Store(Tokens(),error),"single-mutation fixture first Store reached");Check(lease&&!lease->Remove(error)&&!error.isEmpty(),"second mutation Remove rejected before IO");Check(lease&&!lease->Store(Tokens(),error),"second mutation Store rejected before IO");Check(saves==1&&deletes==0,"rejected repeated mutations make no keyring writes");Check(lease&&lease->Rollback(error)&&CloudRaw()==old,"single attempted mutation still rolls back exactly");Check(lease&&!lease->Remove(error),"settled transaction cannot be reused");lease.reset();}
int main(int argc,char**argv){QCoreApplication app(argc,argv);thread worker([]{RejectStore(true);RejectStore(false);AmbiguousStore(false);AmbiguousStore(true);ExternalAfterStore(false);ExternalAfterStore(true);StoreCommit();FailedSaveNoMutation();CancelBeforeBegin();OneMutationOnly();Check(ioOnGui==0&&configOnWorker==0,"Store transaction tests remain worker-only with no config reads");});worker.join();cout<<"{\"checks\":"<<checks<<",\"failures\":"<<failures<<",\"passed\":"<<(failures?"false":"true")<<"}\n";return failures?1:0;}
